import {difficultyFor as tuning} from './difficulty.js';
import {int,pick,shuffle,random,range,esc,btn,note,metric,metrics,controls,grid,cell,log,finish,error,chance,lineSets,neighbors} from './core.js';

export const MORRIS_COORDS=range(3).flatMap(r=>[[r,r],[3,r],[6-r,r],[6-r,3],[6-r,6-r],[3,6-r],[r,6-r],[r,3]]);
export const MORRIS_MILLS=range(3).flatMap(r=>[[0,1,2],[2,3,4],[4,5,6],[6,7,0]].map(l=>l.map(i=>i+r*8))).concat([1,3,5,7].map(i=>[i,i+8,i+16]));
export const MORRIS_EDGES=range(3).flatMap(r=>range(8).map(i=>[r*8+i,r*8+(i+1)%8])).concat([1,3,5,7].flatMap(i=>[[i,i+8],[i+8,i+16]]));
export function inMill(board,i,p){return MORRIS_MILLS.some(l=>l.includes(i)&&l.every(j=>board[j]===p));}
export function morrisMoves(s,p){let empty=range(24).filter(i=>s.board[i]===-1);if(s.reserve[p])return empty.map(to=>({from:-1,to}));let stones=range(24).filter(i=>s.board[i]===p),fly=stones.length===3;return stones.flatMap(from=>empty.filter(to=>fly||MORRIS_EDGES.some(([a,b])=>(a===from&&b===to)||(a===to&&b===from))).map(to=>({from,to})));}
export function morrisCaptures(s,p){let enemy=range(24).filter(i=>s.board[i]===1-p),free=enemy.filter(i=>!inMill(s.board,i,1-p));return free.length?free:enemy;}
export function morrisApply(s,p,m){if(m.from===-1)s.reserve[p]--;else s.board[m.from]=-1;s.board[m.to]=p;return inMill(s.board,m.to,p);}
function morrisOver(s,next){for(let p=0;p<2;p++)if(!s.reserve[p]&&s.board.filter(x=>x===p).length<3){finish(s,p===1,p===1?'A plan set in stone':'Your last mill falls',p===1?'Sage has fewer than three stones.':'You have fewer than three stones.');return true;}if(!morrisMoves(s,next).length){finish(s,next===1,next===1?'Nowhere left to go':'Every route is closed',`${next?'Sage has':'You have'} no legal move.`);return true;}if(s.noCapture>=100){finish(s,false,'A drawn position','One hundred moves without capture. Replay for a decisive result.','Draw');return true;}let key=s.board.join(',')+'|'+s.reserve.join(',')+'|'+next;s.repetitions[key]=(s.repetitions[key]||0)+1;if(s.repetitions[key]>=3){finish(s,false,'A familiar position','Threefold repetition. This game is a draw.','Draw');return true;}return false;}
function morrisBot(s){if(morrisOver(s,1))return;let moves=morrisMoves(s,1),best=-Infinity,choice=moves[0];let threats=MORRIS_MILLS.filter(l=>l.filter(i=>s.board[i]===0).length===2&&l.filter(i=>s.board[i]===-1).length===1).flatMap(l=>l.filter(i=>s.board[i]===-1));for(let m of moves){let b={board:[...s.board],reserve:[...s.reserve]};let mill=morrisApply(b,1,m);let potential=MORRIS_MILLS.reduce((v,l)=>v+(l.filter(i=>b.board[i]===1).length===2&&!l.some(i=>b.board[i]===0)?1:0),0);let score=(mill?100:0)+(threats.includes(m.to)?60:0)+potential*9+MORRIS_EDGES.filter(e=>e.includes(m.to)).length+random(s)*tuning(s,'morris').noise;if(tuning(s,'morris').lookahead){if(mill){let eligible=morrisCaptures(b,1);if(eligible.length)b.board[eligible[0]]=-1;}let counter=morrisMoves(b,0).some(reply=>{let c={board:[...b.board],reserve:[...b.reserve]};return morrisApply(c,0,reply);});if(counter)score-=90;}if(score>best){best=score;choice=m;}}let mill=morrisApply(s,1,choice);s.noCapture++;log(s,`Sage ${choice.from===-1?'placed at':'moved to'} point ${choice.to+1}.`);if(mill){let eligible=morrisCaptures(s,1);if(eligible.length){eligible.sort((a,b)=>{let score=i=>MORRIS_MILLS.filter(l=>l.includes(i)&&l.filter(j=>s.board[j]===0).length===2).length;return score(b)-score(a);});let captured=eligible[0];s.board[captured]=-1;s.noCapture=0;log(s,`Sage formed a mill and captured your stone at ${captured+1}.`);}}morrisOver(s,0);}
export const morris={create(s){s.board=Array(24).fill(-1);s.reserve=[9,9];s.selected=-1;s.capture=false;s.noCapture=0;s.repetitions={};},view(s){let moves=morrisMoves(s,0),eligible=s.capture?morrisCaptures(s,0):[];return metrics(metric(tuning(s,'morris').goal==='first-mill'?'Goal: first mill · reserve':'Your reserve',s.reserve[0]),metric('Sage’s reserve',s.reserve[1]),metric('Stones on board',`${s.board.filter(x=>x===0).length} : ${s.board.filter(x=>x===1).length}`))+`<div class="morris-board board"><svg viewBox="0 0 660 660" aria-hidden="true">${MORRIS_EDGES.map(([a,b])=>`<path d="M${MORRIS_COORDS[a][0]*100+30} ${MORRIS_COORDS[a][1]*100+30}L${MORRIS_COORDS[b][0]*100+30} ${MORRIS_COORDS[b][1]*100+30}"/>`).join('')}</svg>${MORRIS_COORDS.map(([x,y],i)=>`<button class="morris-point ${s.board[i]===0?'white':s.board[i]===1?'black':'empty'} ${s.selected===i?'selected':''} ${eligible.includes(i)?'capturable':''} ${s.selected>=0&&moves.some(m=>m.from===s.selected&&m.to===i)?'destination':''}" style="left:${(x*100+30)/6.6}%;top:${(y*100+30)/6.6}%" data-act="cell" data-value="${i}" aria-label="Point ${i+1}, ${s.board[i]===0?'your stone':s.board[i]===1?'Sage’s stone':'empty'}"><span>${i+1}</span></button>`).join('')}</div>`+note(s.capture?'Mill formed. Capture one of the highlighted dark stones.':s.reserve[0]?'Your turn. Place an ivory stone on an empty point.':s.board.filter(x=>x===0).length===3?'Flying phase. Select your stone, then any empty point.':'Movement phase. Select an ivory stone, then a connected empty point.','accent')+controls(btn('Deselect','cancel','','',s.selected<0));},act(s,a,v){if(a==='cancel'){s.selected=-1;return;}if(a!=='cell')return;let i=+v;if(s.capture){if(!morrisCaptures(s,0).includes(i)){error(s,'Capture an eligible dark stone. Stones in mills are protected while others remain.');return;}s.board[i]=-1;s.capture=false;s.noCapture=0;log(s,`You captured Sage’s stone at ${i+1}.`);morrisBot(s);return;}if(!s.reserve[0]&&s.board[i]===0){s.selected=s.selected===i?-1:i;return;}let m=morrisMoves(s,0).find(m=>m.to===i&&(s.reserve[0]||m.from===s.selected));if(!m){error(s,s.reserve[0]?'Place on an empty point.':'Select your stone, then a legal destination.');return;}let mill=morrisApply(s,0,m);s.selected=-1;s.noCapture++;if(mill&&tuning(s,'morris').goal==='first-mill'){finish(s,true,'Your first mill','Three connected ivory stones complete the Easy lesson. Standard plays the full game.',1);return;}if(mill&&morrisCaptures(s,0).length){s.capture=true;log(s,'You formed a mill. Choose a stone to capture.');}else morrisBot(s);}};

export const HEX_COORDS=[];for(let r=-2;r<=2;r++)for(let q=Math.max(-2,-r-2);q<=Math.min(2,-r+2);q++)HEX_COORDS.push([q,r]);
export const HEX_LINES=[];for(let [q,r] of HEX_COORDS)for(let [dq,dr] of [[1,0],[0,1],[1,-1]]){let ids=range(3).map(k=>HEX_COORDS.findIndex(([x,y])=>x===q+dq*k&&y===r+dr*k));if(ids.every(i=>i>=0))HEX_LINES.push(ids);}
const hexKey=ids=>[...ids].sort((a,b)=>a-b).join(',');
function hexDeal(s){s.numbers=range(19).map(()=>1+int(s,tuning(s,'hex').max));let counts=new Map();for(let l of HEX_LINES){let total=l.reduce((sum,i)=>sum+s.numbers[i],0);counts.set(total,(counts.get(total)||0)+1);}let targets=[...counts].filter(([,n])=>n>=3&&n<=6).map(([v])=>v);s.target=targets.length?pick(s,targets):[...counts].sort((a,b)=>b[1]-a[1])[0][0];s.solutions=HEX_LINES.filter(l=>l.reduce((sum,i)=>sum+s.numbers[i],0)===s.target);s.used=[];s.selected=[];s.phase='study';s.deadline=Date.now()+s.studySeconds*1000;s.studySeconds=tuning(s,'hex').study;if(s.studySeconds)s.deadline=Date.now()+s.studySeconds*1000;else delete s.deadline;s.botMemory=s.numbers.map(n=>random(s)<tuning(s,'hex').recall?n:1+int(s,tuning(s,'hex').max));s.attempts=0;s.botAttempts=0;s.botTried=[];}
function hexEndRound(s){s.round++;if(s.round>3){let [a,b]=s.scores;finish(s,a>b,a>b?'A mind like a hexagon':a===b?'An evenly matched memory':'Sage found the extra line',`Final score: you ${a}, Sage ${b}. A tie is a draw.`,`${a}–${b}`);}else{hexDeal(s);log(s,'A new board. A new set of numbers.');}}
function hexBot(s){if(s.botAttempts>=tuning(s,'hex').botAttempts)return;s.botAttempts++;let choices=HEX_LINES.filter(l=>!s.botTried.includes(hexKey(l))&&!s.used.includes(hexKey(l))&&l.reduce((sum,i)=>sum+s.botMemory[i],0)===s.target);if(!choices.length){log(s,'Sage holds the buzzer.');return;}let l=pick(s,choices),k=hexKey(l);s.botTried.push(k);let correct=s.solutions.some(x=>hexKey(x)===k);s.scores[1]+=correct?1:-1;if(correct)s.used.push(k);log(s,`Sage: ${l.map(i=>String.fromCharCode(65+i)).join('')} ${correct?'+1':'−1'}.`);}
export const hex={create(s){s.round=1;s.scores=[0,0];hexDeal(s);},view(s){let study=s.phase==='study';return metrics(metric('Round',`${Math.min(3,s.round)} / 3`),metric('You : Sage',`${s.scores[0]} : ${s.scores[1]}`),metric(study?'Memorize':'Target',study?(s.difficulty==='relaxed'?'Untimed':`<span data-countdown>${s.studySeconds}s</span>`):s.target))+`<div class="hex-board board">${HEX_COORDS.map(([q,r],i)=>`<button class="hex-cell ${s.selected.includes(i)?'selected':''}" style="left:${50+(q+r/2)*18}%;top:${50+r*16}%" data-act="cell" data-value="${i}" ${study?'disabled':''} aria-label="${String.fromCharCode(65+i)}${study?', '+s.numbers[i]:''}"><small>${String.fromCharCode(65+i)}</small><b>${study||s.difficulty==='relaxed'?s.numbers[i]:String.fromCharCode(65+i)}</b></button>`).join('')}</div>`+(study?controls(btn('Hide numbers · begin','hide','','primary')):controls(btn(`Submit ${s.selected.map(i=>String.fromCharCode(65+i)).join('')||'three cells'}`,'submit','','primary',s.selected.length!==3),btn('Clear','clear'),btn('End this round →','end')))+note(study?'Memorize each number’s position. Only three consecutive cells in a straight row or diagonal qualify.':`Correct +1 · Wrong or repeated −1. Attempts left: ${20-s.attempts}. Accepted lines: ${s.used.map(k=>k.split(',').map(i=>String.fromCharCode(65+Number(i))).join('')).join(', ')||'none'}.`);},act(s,a,v){if(a==='hide'&&s.phase==='study'){s.phase='answer';return;}if(s.phase!=='answer')return;if(a==='cell'){let i=+v;s.selected=s.selected.includes(i)?s.selected.filter(x=>x!==i):s.selected.length<3?[...s.selected,i]:[i];}if(a==='clear')s.selected=[];if(a==='end'){hexEndRound(s);return;}if(a==='submit'&&s.selected.length===3){let k=hexKey(s.selected);if(!HEX_LINES.some(l=>hexKey(l)===k)){error(s,'Select three consecutive cells in a straight line. No point deducted.');return;}let valid=s.solutions.some(l=>hexKey(l)===k)&&!s.used.includes(k);s.scores[0]+=valid?1:-1;s.attempts++;if(valid)s.used.push(k);log(s,`Your ${s.selected.map(i=>String.fromCharCode(65+i)).join('')}: ${valid?'+1':'−1 (wrong or repeated)'}.`);s.selected=[];hexBot(s);if(s.used.length===s.solutions.length||s.attempts>=20)hexEndRound(s);}},tick(s){if(s.phase==='study'&&s.difficulty!=='relaxed'&&Date.now()>=s.deadline){s.phase='answer';return true;}}};

const GOMOKU_SETS={3:lineSets(9,3),5:lineSets(9,5)};
export function gomokuWinner(board,length=5){for(let l of GOMOKU_SETS[length])if(board[l[0]]!==-1&&l.every(i=>board[i]===board[l[0]]))return board[l[0]];return -1;}
function gomokuBot(s){let lines=GOMOKU_SETS[tuning(s,'gomoku').line];let empty=range(81).filter(i=>s.board[i]===-1),best=-Infinity,choice=empty[0];for(let i of empty){let score=0;for(let p of [0,1]){let b=[...s.board];b[i]=p;if(gomokuWinner(b,tuning(s,'gomoku').line)===p)score+=p===1?1e7:1e6;score+=lines.filter(l=>l.includes(i)&&!l.some(j=>b[j]===1-p)).reduce((v,l)=>v+Math.pow(6,l.filter(j=>b[j]===p).length)*(p===1?1.1:1),0);}score+=neighbors(i,9,true).filter(j=>s.board[j]!==-1).length*3-((i%9-4)**2+(Math.floor(i/9)-4)**2)*.1+random(s)*tuning(s,'gomoku').noise;if(tuning(s,'gomoku').forks){let board=[...s.board];board[i]=1;let threats=p=>new Set(lines.filter(l=>l.filter(j=>board[j]===p).length===4&&l.filter(j=>board[j]===-1).length===1).map(l=>l.find(j=>board[j]===-1))).size;if(threats(1)>=2)score+=500000;if(threats(0)>=2)score-=500000;}if(score>best){best=score;choice=i;}}if(choice!==undefined){s.board[choice]=1;s.lastBot=choice;s.history.push(choice);}}
export const gomoku={create(s){s.board=Array(81).fill(-1);s.lastYou=-1;s.lastBot=-1;s.turns=0;s.history=[];},view(s){return metrics(metric('Your moves',s.turns),metric('Goal',tuning(s,'gomoku').line+' in a row'),metric('You','Ivory'))+grid(9,s.board.map((p,i)=>cell(i,p===-1?'':`<i class="go-stone ${s.outcome||tuning(s,'gomoku').visiblePairs===Infinity||s.history.slice(-tuning(s,'gomoku').visiblePairs*2).includes(i)?p===0?'white':'black':'hidden'}"></i>`,`${p===-1?'empty-intersection':''} ${i===s.lastYou||i===s.lastBot?'last-move':''}`,p!==-1)),'gomoku-board')+note(s.difficulty==='relaxed'?'Easy lesson: every stone stays visible. Connect three ivory stones in a row.': `The latest ${tuning(s,'gomoku').visiblePairs} pair(s) stay face-up. Remember ownership. Connect five ivory stones; the dealer plays dark.`);},act(s,a,v){if(a!=='cell'||s.board[+v]!==-1)return;s.board[+v]=0;s.lastYou=+v;s.history.push(+v);s.turns++;if(gomokuWinner(s.board,tuning(s,'gomoku').line)===0){finish(s,true,'The invisible line',`${tuning(s,'gomoku').line} ivory stones connect. The chamber is yours.`,s.turns);return;}if(s.board.every(x=>x!==-1)){finish(s,false,'The chamber is full','No five-in-a-row. The game is a draw.','Draw');return;}gomokuBot(s);if(gomokuWinner(s.board,tuning(s,'gomoku').line)===1)finish(s,false,'The dealer remembers',`${tuning(s,'gomoku').line} dark stones connect. The board is revealed.`,s.turns);else if(s.board.every(x=>x!==-1))finish(s,false,'The chamber is full','No five-in-a-row. The game is a draw.','Draw');}};
